What does this program print? It prints two lines; type them separated by a single space.

```perl
use strict;
use warnings;
use feature qw(say);

package Instrument {
    sub new   { my ($class, %args) = @_; return bless {%args}, $class }
    sub sound { 'a note' }
    sub play  { my ($self) = @_; return "$self->{name} plays " . $self->sound }
}
package Drum {
    use parent -norequire, 'Instrument';
    sub sound { 'boom' }
}
package main;
say Drum->new(name => 'Kofi')->play;
say Instrument->new(name => 'Mei')->play;
```

