What does this program print?

```perl
use strict;
use warnings;
use feature qw(say);

package Base { sub new { return bless {}, shift } sub hello { 'base' } }
package Mid  { use parent -norequire, 'Base'; sub hello { my ($s) = @_; return 'mid+' . $s->SUPER::hello() } }
package Top  { use parent -norequire, 'Mid';  sub hello { my ($s) = @_; return 'top+' . $s->SUPER::hello() } }
package main;
say Top->new->hello;
```

What number does this program print?

```perl
use strict;
use warnings;
use feature qw(say);

package Ticket {
    my $issued = 0;
    sub new    { my ($class) = @_; $issued++; return bless { number => $issued }, $class }
    sub issued { $issued }
    sub number { $_[0]{number} }
}
package VipTicket { use parent -norequire, 'Ticket' }
package main;
my @t = map { Ticket->new } 1 .. 2;
my @v = map { VipTicket->new } 1 .. 3;
say Ticket->issued + $v[-1]->number;
```
